            outline.addQuadCurve(to: CGPoint(x: 3, y: 15), control: CGPoint(x: 3, y: 19))
            outline.addQuadCurve(to: CGPoint(x: 7, y: 11), control: CGPoint(x: 3, y: 11))
            outline.addQuadCurve(to: CGPoint(x: 13, y: 4), control: CGPoint(x: 7, y: 4))
            outline.addQuadCurve(to: CGPoint(x: 19, y: 10), control: CGPoint(x: 18, y: 4))
            outline.addQuadCurve(to: CGPoint(x: 22, y: 15), control: CGPoint(x: 22, y: 11))
            outline.addQuadCurve(to: CGPoint(x: 18, y: 19), control: CGPoint(x: 22, y: 19))
            outline.closeSubpath()
        case .shield:
            outline.move(to: CGPoint(x: 12, y: 3))
            outline.addLine(to: CGPoint(x: 20, y: 6))
            outline.addLine(to: CGPoint(x: 20, y: 12))
            outline.addQuadCurve(to: CGPoint(x: 12, y: 21), control: CGPoint(x: 20, y: 18))
            outline.addQuadCurve(to: CGPoint(x: 4, y: 12), control: CGPoint(x: 4, y: 18))
            outline.addLine(to: CGPoint(x: 4, y: 6))
            outline.closeSubpath()
            outline.move(to: CGPoint(x: 8, y: 12))
            outline.addLine(to: CGPoint(x: 11, y: 15))
            outline.addLine(to: CGPoint(x: 16, y: 9))
        case .code:
            outline.move(to: CGPoint(x: 8, y: 6))
            outline.addLine(to: CGPoint(x: 3, y: 12))
            outline.addLine(to: CGPoint(x: 8, y: 18))
            outline.move(to: CGPoint(x: 16, y: 6))
            outline.addLine(to: CGPoint(x: 21, y: 12))
            outline.addLine(to: CGPoint(x: 16, y: 18))
            outline.move(to: CGPoint(x: 14, y: 4))
            outline.addLine(to: CGPoint(x: 10, y: 20))
        case .duplicate:
            outline.move(to: CGPoint(x: 11, y: 8))
            outline.addLine(to: CGPoint(x: 18, y: 8))
            outline.addQuadCurve(to: CGPoint(x: 21, y: 11), control: CGPoint(x: 21, y: 8))
            outline.addLine(to: CGPoint(x: 21, y: 18))
            outline.addQuadCurve(to: CGPoint(x: 18, y: 21), control: CGPoint(x: 21, y: 21))
            outline.addLine(to: CGPoint(x: 11, y: 21))
            outline.addQuadCurve(to: CGPoint(x: 8, y: 18), control: CGPoint(x: 8, y: 21))
            outline.addLine(to: CGPoint(x: 8, y: 11))
            outline.addQuadCurve(to: CGPoint(x: 11, y: 8), control: CGPoint(x: 8, y: 8))
            outline.closeSubpath()
            outline.move(to: CGPoint(x: 16, y: 4))
            outline.addLine(to: CGPoint(x: 7, y: 4))
            outline.addQuadCurve(to: CGPoint(x: 3, y: 8), control: CGPoint(x: 3, y: 4))
            outline.addLine(to: CGPoint(x: 3, y: 16))
            outline.move(to: CGPoint(x: 12, y: 14.5))
            outline.addLine(to: CGPoint(x: 17, y: 14.5))
            outline.move(to: CGPoint(x: 14.5, y: 12))
            outline.addLine(to: CGPoint(x: 14.5, y: 17))
        case .freeze:
            outline.move(to: CGPoint(x: 7, y: 4))
            outline.addLine(to: CGPoint(x: 17, y: 4))
            outline.addQuadCurve(to: CGPoint(x: 21, y: 8), control: CGPoint(x: 21, y: 4))
            outline.addLine(to: CGPoint(x: 21, y: 16))
            outline.addQuadCurve(to: CGPoint(x: 17, y: 20), control: CGPoint(x: 21, y: 20))
            outline.addLine(to: CGPoint(x: 7, y: 20))
            outline.addQuadCurve(to: CGPoint(x: 3, y: 16), control: CGPoint(x: 3, y: 20))
            outline.addLine(to: CGPoint(x: 3, y: 8))
            outline.addQuadCurve(to: CGPoint(x: 7, y: 4), control: CGPoint(x: 3, y: 4))
            outline.closeSubpath()
            solid.move(to: CGPoint(x: 9, y: 8))
            solid.addLine(to: CGPoint(x: 10, y: 8))
            solid.addQuadCurve(to: CGPoint(x: 11, y: 9), control: CGPoint(x: 11, y: 8))
            solid.addLine(to: CGPoint(x: 11, y: 15))
            solid.addQuadCurve(to: CGPoint(x: 10, y: 16), control: CGPoint(x: 11, y: 16))
            solid.addLine(to: CGPoint(x: 9, y: 16))
            solid.addQuadCurve(to: CGPoint(x: 8, y: 15), control: CGPoint(x: 8, y: 16))
            solid.addLine(to: CGPoint(x: 8, y: 9))
            solid.addQuadCurve(to: CGPoint(x: 9, y: 8), control: CGPoint(x: 8, y: 8))
            solid.closeSubpath()
            solid.move(to: CGPoint(x: 15, y: 8))
            solid.addLine(to: CGPoint(x: 16, y: 8))
            solid.addQuadCurve(to: CGPoint(x: 17, y: 9), control: CGPoint(x: 17, y: 8))
            solid.addLine(to: CGPoint(x: 17, y: 15))
            solid.addQuadCurve(to: CGPoint(x: 16, y: 16), control: CGPoint(x: 17, y: 16))
            solid.addLine(to: CGPoint(x: 15, y: 16))
            solid.addQuadCurve(to: CGPoint(x: 14, y: 15), control: CGPoint(x: 14, y: 16))
            solid.addLine(to: CGPoint(x: 14, y: 9))
            solid.addQuadCurve(to: CGPoint(x: 15, y: 8), control: CGPoint(x: 14, y: 8))
            solid.closeSubpath()
        }
        let scale = min(rect.width, rect.height) / 24
        return (filled ? solid : outline).applying(CGAffineTransform(scaleX: scale, y: scale))
            .applying(CGAffineTransform(translationX: rect.minX + (rect.width - 24 * scale) / 2, y: rect.minY + (rect.height - 24 * scale) / 2))
    }
}
